import fs from "node:fs";
import path from "node:path";

import { artifacts } from "hardhat";

import { EXPORTED_CONTRACTS, EXPORTED_NETWORKS, PACKAGE_ROOT, readDeployments } from "./deployments";

export const GENERATED_FILE = path.join(PACKAGE_ROOT, "generated", "index.ts");

/**
 * Writes generated/index.ts: per-network chain id + contract addresses, and each exported
 * contract's ABI as a const (so viem/ethers callers get typed function names).
 */
export async function writeGeneratedModule(): Promise<string> {
  const lines: string[] = [
    "// Generated by packages/fhevm/scripts/export.ts. Do not edit by hand:",
    "// run `npm run export -w @skirm/fhevm` (deploy:sepolia runs it too).",
    "",
    "/** Contracts exported to the web. */",
    `export type ContractName = ${EXPORTED_CONTRACTS.map((c) => JSON.stringify(c)).join(" | ")};`,
    "",
    "/** Chain id and each contract's address on a network (null when not deployed there yet). */",
    "export interface FhevmNetwork {",
    "  chainId: number;",
    "  contracts: Record<ContractName, `0x${string}` | null>;",
    "}",
    "",
  ];

  for (const network of EXPORTED_NETWORKS) {
    const deployed = readDeployments(network);
    const contracts = Object.fromEntries(
      EXPORTED_CONTRACTS.map((name) => [name, deployed?.contracts[name]?.address ?? null]),
    );
    const chainId = deployed?.chainId ?? (network === "sepolia" ? 11155111 : 0);
    lines.push(
      `export const ${network}: FhevmNetwork = ${JSON.stringify({ chainId, contracts }, null, 2)};`,
      "",
    );
  }

  for (const name of EXPORTED_CONTRACTS) {
    const { abi } = await artifacts.readArtifact(name);
    lines.push(`export const ${name}Abi = ${JSON.stringify(abi, null, 2)} as const;`, "");
  }

  fs.mkdirSync(path.dirname(GENERATED_FILE), { recursive: true });
  fs.writeFileSync(GENERATED_FILE, lines.join("\n"));
  return GENERATED_FILE;
}
